// src/app/p/[slug]/page.tsx
import { Metadata } from "next";
import { notFound } from "next/navigation";
import { getProductBySlug, getSimilarProducts } from "@/data/store-";
import ProductPageMaster from "@/features/product-page";

interface Props {
  params: { slug: string };
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const product = await getProductBySlug(params.slug);
  if (!product) return { title: "Product Not Found" };

  return {
    title: `${product.name} | Premium ${product.quality} Store`,
    description: product.description,
    openGraph: {
      title: product.name,
      description: product.description,
      images: [{ url: product.promoImage }],
    },
    alternates: {
      canonical: `https://yourdomain.com/p/${params.slug}`,
    },
  };
}

export default async function Page({ params }: Props) {
  const product = await getProductBySlug(params.slug);

  if (!product) {
    <div className="min-h-screen flex items-center justify-center bg-black text-white">
      <h1 className="text-3xl font-bold uppercase tracking-tighter italic">
        {params.slug} Produc's Data Not Found:
      </h1>
    </div>;
  }

  // const similarProducts = await getSimilarProducts(
  //   product.category,
  //   product.id
  // );

  return (
    <ProductPageMaster product={product} />
  );
}
